use atlas_native_storage_contract::{create_workspace, add_file, replace_file, set_file_description};
use std::{fs,path::PathBuf,time::{SystemTime,UNIX_EPOCH},os::unix::fs::symlink};
use rusqlite::{Connection,params};
static SEQ:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
fn root()->PathBuf{std::env::temp_dir().join(format!("atlas-file-test-{}-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos(),SEQ.fetch_add(1,std::sync::atomic::Ordering::Relaxed)))}
fn row(p:&PathBuf,id:&str)->(String,String,String){let c=Connection::open(p.join("atlas.sqlite3")).unwrap();c.query_row("SELECT path,title,text_status FROM objects WHERE id=?",[id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap()}
fn hits(p:&PathBuf,id:&str,word:&str)->i64{Connection::open(p.join("atlas.sqlite3")).unwrap().query_row("SELECT count(*) FROM search_chunks WHERE object_id=? AND search_chunks MATCH ?",params![id,word],|r|r.get(0)).unwrap()}
#[test] fn text_file_preserves_bytes_and_indexes(){let p=root();create_workspace(&p).unwrap();let bytes="строка магнолия\n".as_bytes();let id=add_file(&p,"текст.txt",bytes).unwrap();let(path,title,status)=row(&p,&id);assert_eq!(fs::read(p.join(path)).unwrap(),bytes);assert_eq!(title,"текст.txt");assert_eq!(status,"available");assert!(hits(&p,&id,"магнолия")>0);fs::remove_dir_all(p).unwrap();}
#[test] fn unknown_file_indexes_only_name_and_description(){let p=root();create_workspace(&p).unwrap();let id=add_file(&p,"orchid.py",b"hiddenuniqueword").unwrap();let(path,_,status)=row(&p,&id);assert_eq!(fs::read(p.join(path)).unwrap(),b"hiddenuniqueword");assert_eq!(status,"unsupported");assert_eq!(hits(&p,&id,"hiddenuniqueword"),0);assert!(hits(&p,&id,"orchid")>0);set_file_description(&p,&id,"gardenuniqueword").unwrap();assert!(hits(&p,&id,"gardenuniqueword")>0);fs::remove_dir_all(p).unwrap();}
#[test] fn replace_preserves_id_and_reindexes(){let p=root();create_workspace(&p).unwrap();let id=add_file(&p,"one.md",b"oldunique").unwrap();replace_file(&p,&id,"two.txt",b"newunique").unwrap();let(path,title,_)=row(&p,&id);assert_eq!(title,"two.txt");assert_eq!(fs::read(p.join(path)).unwrap(),b"newunique");assert_eq!(hits(&p,&id,"oldunique"),0);assert!(hits(&p,&id,"newunique")>0);fs::remove_dir_all(p).unwrap();}
#[test] fn reject_names_and_symlink_escape(){let p=root();let outside=root();fs::create_dir(&outside).unwrap();create_workspace(&p).unwrap();assert!(add_file(&p,"../escape.txt",b"bad").is_err());assert!(add_file(&p,"sub/escape.txt",b"bad").is_err());fs::remove_dir(p.join("files")).unwrap();symlink(&outside,p.join("files")).unwrap();assert!(add_file(&p,"escape.txt",b"bad").is_err());assert_eq!(fs::read_dir(&outside).unwrap().count(),0);fs::remove_dir_all(p).unwrap();fs::remove_dir_all(outside).unwrap();}
#[test] fn stream_add_works_with_small_reads(){use std::io::{self,Read};struct Slow{left:usize}impl Read for Slow{fn read(&mut self,b:&mut[u8])->io::Result<usize>{if self.left==0{return Ok(0)} let n=self.left.min(b.len()).min(7);b[..n].fill(b'x');self.left-=n;Ok(n)}}let p=root();create_workspace(&p).unwrap();let mut src=Slow{left:1024*1024};let id=atlas_native_storage_contract::add_file_stream(&p,"large.bin",&mut src).unwrap();let(path,_,_)=row(&p,&id);assert_eq!(fs::metadata(p.join(path)).unwrap().len(),1024*1024);fs::remove_dir_all(p).unwrap();}
